 tx:[["Réhydratation : SRO (plan B de l'OMS) puis perfusion si besoin",/\bsro\b|rehydrat|perfusion|plan b|ringer|sels de rehydratation/,3],["Antibiotique adapté à l'antibiogramme (ciprofloxacine ou azithromycine 3 à 5 jours)",/ciprofloxacine|azithromycine|antibio|cotrimoxazole|ceftriaxone/,4],["Zinc 20 mg par jour pendant 10 jours",/zinc/,2],["Pas d'antidiarrhéique ni d'antispasmodique (risque d'aggraver la dysenterie)",/pas d.antidiarrh|pas d.antispasm|sans antidiarrh/,2],["Alimentation poursuivie, hygiène des mains et de l'eau",/aliment|hygiene|eau|mains|lavage/,1]],
